-- Pre-8E repair R7/T034-T037: transcript-scoped YouTube transcript collection.
-- Historical workflow migrations remain untouched. This versions
-- youtube.get_transcript so the primary path collects transcript segments
-- directly (ytd-transcript-segment-renderer, bounded to 100 items, visibleOnly
-- false) instead of chunked full-page page.read loops, so the model-facing
-- output excludes description/comments/recommendations noise. The v4 chunked
-- text loop is preserved verbatim as the bounded fallback branch for DOM
-- variants where the segment query returns nothing. The unconditional
-- previousActive tabs.get moves into the activation branch (background-first
-- round-trip reduction); activation stays a bounded render fallback with
-- active-tab restore.
--
-- No public MCP tool/schema, protocol, primitive count, production schema, VM,
-- signing, auth, or transport boundary changes are introduced here.

select public.opera_register_workflow(
  'youtube.get_transcript',
  $wf${"steps":[{"id":"yt","type":"command","method":"tabs.find","params":{"limit":10,"urlContains":"youtube.com/watch"}},{"else":[{"code":"YOUTUBE_TAB_NOT_FOUND","type":"fail","message":"No YouTube watch tab is open."}],"then":[{"name":"tabId","type":"set","value":{"$ref":"steps.yt.result.tab.id"}}],"type":"if","condition":{"op":"exists","left":{"$ref":"steps.yt.result.tab"}}},{"id":"watch","type":"command","method":"page.wait_for","params":{"tabId":{"$ref":"vars.tabId"},"selector":"ytd-watch-flexy","timeoutMs":10000}},{"name":"panelWasOpen","type":"set","value":false},{"name":"openMethod","type":"set","value":"none"},{"name":"activatedForRender","type":"set","value":false},{"id":"panel","type":"command","method":"page.query","params":{"index":0,"limit":5,"tabId":{"$ref":"vars.tabId"},"selector":"ytd-transcript-renderer, ytd-engagement-panel-section-list-renderer[target-id*=\"transcript\"][visibility=\"ENGAGEMENT_PANEL_VISIBILITY_EXPANDED\"]","visibleOnly":false},"continueOnError":true},{"else":[{"id":"transcript","type":"command","method":"page.find","params":{"text":"Show transcript","limit":5,"tabId":{"$ref":"vars.tabId"}},"continueOnError":true},{"else":[{"name":"transcriptRef","type":"set","value":{"$ref":"steps.transcript.result.item.ref"}}],"then":[{"id":"expand","type":"command","method":"page.query","params":{"index":0,"limit":5,"tabId":{"$ref":"vars.tabId"},"selector":"#description-inline-expander #expand, ytd-text-inline-expander #expand, tp-yt-paper-button#expand"},"continueOnError":true},{"else":[],"then":[{"id":"expandclick","type":"command","method":"page.click","params":{"ref":{"$ref":"steps.expand.result.item.ref"},"tabId":{"$ref":"vars.tabId"},"trusted":false},"continueOnError":true}],"type":"if","condition":{"op":"exists","left":{"$ref":"steps.expand.result.item"}}},{"id":"waittranscript","type":"command","method":"page.wait_for","params":{"text":"Show transcript","tabId":{"$ref":"vars.tabId"},"timeoutMs":5000}},{"name":"transcriptRef","type":"set","value":{"$ref":"steps.waittranscript.result.item.ref"}}],"type":"if","condition":{"op":"not_exists","left":{"$ref":"steps.transcript.result.item"}}},{"id":"openSynthetic","type":"command","method":"page.click","params":{"ref":{"$ref":"vars.transcriptRef"},"tabId":{"$ref":"vars.tabId"},"trusted":false},"continueOnError":true},{"id":"panelFast","type":"command","method":"page.wait_for","params":{"tabId":{"$ref":"vars.tabId"},"selector":"ytd-transcript-renderer, ytd-engagement-panel-section-list-renderer[target-id*=\"transcript\"][visibility=\"ENGAGEMENT_PANEL_VISIBILITY_EXPANDED\"]","timeoutMs":1200,"visibleOnly":false},"continueOnError":true},{"else":[{"id":"transcriptFresh","type":"command","method":"page.find","params":{"text":"Show transcript","limit":5,"tabId":{"$ref":"vars.tabId"}}},{"id":"openTrusted","type":"command","method":"page.click","params":{"ref":{"$ref":"steps.transcriptFresh.result.item.ref"},"tabId":{"$ref":"vars.tabId"},"trusted":true}},{"id":"panelTrusted","type":"command","method":"page.wait_for","params":{"tabId":{"$ref":"vars.tabId"},"selector":"ytd-transcript-renderer, ytd-engagement-panel-section-list-renderer[target-id*=\"transcript\"][visibility=\"ENGAGEMENT_PANEL_VISIBILITY_EXPANDED\"]","timeoutMs":8000,"visibleOnly":false}},{"name":"openMethod","type":"set","value":"trusted"}],"then":[{"name":"openMethod","type":"set","value":"synthetic"}],"type":"if","condition":{"op":"exists","left":{"$ref":"steps.panelFast.result.item"}}}],"then":[{"name":"panelWasOpen","type":"set","value":true},{"name":"openMethod","type":"set","value":"already-open"}],"type":"if","condition":{"op":"exists","left":{"$ref":"steps.panel.result.item"}}},{"id":"segmentFast","type":"command","method":"page.wait_for","params":{"tabId":{"$ref":"vars.tabId"},"selector":"ytd-transcript-segment-renderer","timeoutMs":1200,"visibleOnly":false},"continueOnError":true},{"else":[],"then":[{"type":"command","id":"prevActive","method":"tabs.get","params":{"tabId":{"$ref":"vars.tabId"}}},{"id":"activateForRender","type":"command","method":"tabs.activate","params":{"tabId":{"$ref":"vars.tabId"},"focusWindow":false}},{"type":"set","name":"prevActiveId","value":{"$ref":"steps.prevActive.result.tab.id"}},{"name":"activatedForRender","type":"set","value":true},{"id":"segmentReady","type":"command","method":"page.wait_for","params":{"tabId":{"$ref":"vars.tabId"},"selector":"ytd-transcript-segment-renderer","timeoutMs":6000,"visibleOnly":false}}],"type":"if","condition":{"op":"not_exists","left":{"$ref":"steps.segmentFast.result.item"}}},{"type":"command","id":"segments","method":"page.query","continueOnError":true,"params":{"tabId":{"$ref":"vars.tabId"},"selector":"ytd-transcript-segment-renderer","limit":100,"visibleOnly":false}},{"type":"if","id":"segmentsAvailable","condition":{"left":{"$ref":"steps.segments.result.count"},"op":"truthy"},"then":[],"else":[{"name":"text","type":"set","value":""},{"name":"offset","type":"set","value":0},{"id":"chunks","type":"repeat","steps":[{"id":"read","type":"command","method":"page.read","params":{"limit":12000,"tabId":{"$ref":"vars.tabId"},"offset":{"$ref":"vars.offset"},"maxElements":1,"includeElements":false}},{"name":"text","type":"set","value":{"$concat":[{"$ref":"vars.text"},{"$ref":"steps.read.result.page.text"}]}},{"name":"offset","type":"set","value":{"$ref":"steps.read.result.page.nextOffset"}}],"until":{"op":"falsey","left":{"$ref":"steps.read.result.page.hasMore"}},"failOnLimit":false,"maxIterations":30}]},{"id":"tab","type":"command","method":"tabs.get","params":{"tabId":{"$ref":"vars.tabId"}}},{"else":[],"then":[{"else":[],"then":[{"id":"restoreActive","type":"command","method":"tabs.activate","params":{"tabId":{"$ref":"vars.prevActiveId"},"focusWindow":false},"continueOnError":true}],"type":"if","condition":{"op":"ne","left":{"$ref":"vars.prevActiveId"},"right":{"$ref":"vars.tabId"}}}],"type":"if","condition":{"op":"truthy","left":{"$ref":"vars.activatedForRender"}}}],"output":{"tab":{"$ref":"steps.tab.result.tab"},"segments":{"$ref":"steps.segments.result.items"},"segmentCount":{"$ref":"steps.segments.result.count"},"openMethod":{"$ref":"vars.openMethod"},"panelWasOpen":{"$ref":"vars.panelWasOpen"},"activatedForRender":{"$ref":"vars.activatedForRender"}}}$wf$::jsonb,
  'Collect a clean transcript via segment-scoped queries with the chunked full-text reader kept as a bounded fallback.',
  true
);
